139	    /* ===== SKIP TO CONTENT (accessibility) ===== */
140	    .skip-to-content {
141	      position: absolute; top: -40px; left: 6px; background: var(--accent);
142	      color: white; padding: 8px 12px; text-decoration: none;
143	      border-radius: 4px; opacity: 0; pointer-events: none;
144	      transition: all 0.2s; z-index: 10000;
