225	        if (dropdown) dropdown.classList.remove('open');
226	      }
227	    });
228	    document.addEventListener('keydown', e => { 
229	      if (e.key === 'Escape') {
230	        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
231	        if (dropdown) dropdown.classList.remove('open');
