235	    // === Theme (class-based, OS detection on first visit) ===
236	    var savedTheme = localStorage.getItem('viz-theme');
237	    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
238	    function applyTheme(t) {
239	      document.documentElement.className = 'theme-' + t;
240	      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
241	      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
242	      localStorage.setItem('viz-theme', t);
243	      currentTheme = t;
244	      if (typeof onThemeChange === 'function') onThemeChange();
